module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [9:0] sr;
reg [8:0] neg_divisor;
reg [3:0] cnt;
reg start_cnt;
reg [15:0] temp_res;

localparam IDLE = 3'd0;
localparam DIVIDE = 3'd1;
localparam DONE = 3'd2;

reg [8:0] sub_result;
reg carry_out;
reg [8:0] mux_out;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        abs_dividend <= 8'h0;
        abs_divisor <= 8'h0;
        sr <= 10'h0;
        neg_divisor <= 9'h0;
        cnt <= 4'h0;
        start_cnt <= 1'b0;
        temp_res <= 16'h0;
        res_valid <= 1'b0;
    end else begin
        if ((opn_valid == 1'b1) && (res_valid == 1'b0)) begin
            abs_dividend <= (sign & dividend[7]) ? (~dividend + 1'b1) : dividend;
            abs_divisor <= (sign & divisor[7]) ? (~divisor + 1'b1) : divisor;

            sr <= {1'b0, abs_dividend} << 1;
            neg_divisor <= ~{1'b0, abs_divisor} + 1'b1;
            cnt <= 4'h1;
            start_cnt <= 1'b1;
        end else if (start_cnt) begin
            if (cnt[3]) begin
                start_cnt <= 1'b0;
                cnt <= 4'h0;

                temp_res <= {sr[8:0], 8'h0};
                res_valid <= 1'b1;
            end else begin
                cnt <= cnt + 1'b1;
                {carry_out, sub_result} <= {1'b0, sr} + neg_divisor;
                mux_out <= (carry_out) ? sub_result : {sr[8:0], 1'b0};
                sr <= mux_out;
            end
        end

        if (rst || (cnt != 4'h0) || !res_valid) begin
            res_valid <= 1'b0;
        end
    end
end

assign result = temp_res;
endmodule
